local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["5e066350a1f5e9ff"] = { "Un'altra consegna! Fantastico. Mettila lì vicino alla pila e parliamo del tuo compenso.", "." },
  ["5e06bad2cfda014b"] = { "Allora... non è che per caso hai un forziere qui intorno che contiene, diciamo, un guanto che gli ogre Gordok considerano un manufatto inestimabile?", "." },
  ["5e0865f8ed185df8"] = { "Lakota'mani tuona dentro di te, {name}.", "." },
  ["5e0e31f14be498d0"] = { "Come posso ottenere l'Evoroot?", "." },
  ["5e19fe136aca1a63"] = { "Il Signore del Fuoco e chiunque osi sbarrarmi la strada vacilleranno sotto la mia ira.", "." },
  ["5e286aab4f1a15ed"] = { "Ma... che gentile da parte tua. Immagino che tu stia dedicando il tuo tempo alla Children's Week, vero, {class}? Be', meriti un encomio. È fondamentale ricordarsi di chi è meno fortunato, soprattutto dei bambini.\n\nSarò felice di firmarti un autografo. Ecco a te.", "." },
  ["5e2deb28e73e85af"] = { "Sei <nuovo/nuova> qui? Be', allora dimmi cosa cerchi.", "." },
  ["5e4316a1c91e4aa9"] = { "Cosa succederebbe se il Fruit of Fertility, o la Felvine, cadesse del tutto preda della corruzione?", "." },
  ["5e5077acf5caa716"] = { "<Il guardiamorte Billmuth si agita distratto mentre si guarda intorno nervosamente. È chiaro che si sente molto a disagio qui.>", "." },
  ["5e59f49174ee62b3"] = { "Trova ⟦Tarshaw Jaggedscar=Tarshaw Frangitaglio⟧ nella caserma sul lato est di ⟦Razor Hill=Tranciacolle⟧. Porta orgoglio e onore all'⟦Horde=Orda⟧, giovane!", "." },
  ["5e5a972a0a71cded"] = { "L'incantamento è di famiglia da generazioni. Ho imparato in tenera età, proprio come sta facendo ora mio figlio.", "." },
  ["5e5dded8d2a73174"] = { "Salve, <giovanotto/signorina>. Sono Eva Sarkhoff e questo è mio marito, Lucien. È un piacere fare la tua conoscenza.", "." },
  ["5e5e0e2b873ceea0"] = { "Sono <pronto/pronta>, storico Archesonus.", "." },
  ["5e61d350ac0a7004"] = { "Non posso credere che i funzionari di ⟦Stormwind=Roccavento⟧ mandino il grosso del nostro esercito all'estero... quando il fronte interno è così sotto pressione!\n\nCon i ladri che arrivano dalle ⟦Westfall=Marche Occidentali⟧ e gli gnoll che avanzano da est e da ovest, c'è da stupirsi che ⟦Stormwind=Roccavento⟧ stessa non sia sotto assedio.", "." },
  ["5e64b99ac77617f7"] = { "Allontanati dagli effetti personali del tenente!", "." },
  ["5e66ee4e5d824461"] = { "Conciatura", "." },
  ["5e6deefa212bf231"] = { "Successo! Ti assicuro che non mi aspettavo niente di meno dal <mio/mia> <allievo/allieva> migliore.\n\nHai dimostrato il tuo valore, e ti mostrerò volentieri il metodo per evocare la succube che hai sottomesso. Ora va', hai molto da imparare, e la prossima volta che ti vedrò mi aspetto che tu abbia raggiunto la vera padronanza della tua succube.\n\nLascia il dolore di Dogran e Zankaja a quelli di noi che hanno più anni sulle spalle, ma ricordalo, e tienilo come protezione contro le lusinghe del potere oscuro che oggi hai imparato a evocare.", "." },
  ["5e6e2c0fc1226a4f"] = { "Il maestro dei grifoni supervisiona i voli dei grifoni da ⟦Stormwind=Roccavento⟧. Se vuoi fare un giro, è lì che devi andare.", "." },
  ["5e6f8dc5477d2779"] = { "Mi spiace, <fratello/sorella>, ma non venderò i miei raptor a chi non si è dimostrato osannato presso la tribù ⟦Darkspear=Lanciascura⟧. Quando prenderai posizione e ti dimostrerai almeno <osannato/osannata> presso di noi, allora metterò a tua disposizione i miei raptor.", "." },
  ["5e705df171f26016"] = { "Guarda nel calderone, {name}. Marg desidera parlare...", "." },
  ["5e70772208ff9221"] = { "Non farmi perdere tempo. Ho progetti di ricerca più vecchi di te. Va' a parlare con il dottor Martin Felben nell'Apothecarium di ⟦Undercity=Sepulcra⟧. È un Reietto che probabilmente saprà insegnarti le basi.", "." },
  ["5e76351d169f0b31"] = { "Ok, il piatto di pesce era il tuo, comandante. Buon appetito!", "." },
  ["5e76806378789501"] = { "Ack! Aiuto! Uno gnomo impazzito vuole uccidermi!", "." },
  ["5e7c7bb6336df96f"] = { "Haleh, ho perso l'⟦Drakefire Amulet=Amuleto Fuocodraco⟧. Potresti forgiarne un altro?", "." },
  ["5e81b85b164c4438"] = { "Allora, a quanto pare cerchiamo entrambi Hogral Bakkan. È un nano, poco ma sicuro, quindi prima o poi andrà alla ⟦Thunderbrew Distillery=Distilleria Birratuono⟧ per una birra... potrebbe perfino essere già lì.", "." },
  ["5e8482c113f46179"] = { "ALT! C'erano... segnalazioni... di un... disturbo.", "." },
  ["5e86cd8343b297e9"] = { "Ciao, cosa desideri?", "." },
  ["5e8804dc898d1917"] = { "Feccia dei Piccatonante! Nella mia rocca?! Uccideteli tutti!", "." },
  ["5e8a911b2fc25773"] = { "E ora sai tutto ciò che c'è da sapere, mortale...", "." },
  ["5e8d31de0cc97648"] = { "Spero che tu ti sia res<o/a> utile al nostro caro amico, lo speziale Faustin.", "." },
  ["5e8f87f8889d08e9"] = { "Il capitano Galvangar è il fidato braccio destro di ⟦Drek'Thar=Drek'thar⟧. Guida le forze dell'⟦Horde=Orda⟧ dal ⟦Iceblood Garrison=Presidio di Brinarossa⟧, nella parte meridionale del ⟦Field of Strife=Pian della Discordia⟧.\n\nIl capitano Galvangar è stato ucciso.", "." },
  ["5e9e58d798f9d8aa"] = { "Ora vive al fianco dell'imperatore Thaurissan. La tiene sotto una sorta di potente incantesimo che le altera la mente... e io me ne sto qui, del tutto impotente.", "." },
  ["5ea8de58627aa9af"] = { "La natura fornisce tutto ciò di cui abbiamo bisogno. Parla con Komin ⟦Winterhoof=Zoccolo Artico⟧ a Holistic Herbalism, sull'altura di mezzo.", "." },
  ["5eab45f079ccf746"] = { "Se qualcuno ha ricomposto lo scettro magico delle sabbie, allora la guerra contro gli insetti è vicina. Non vedo l'ora, {class}! Gli ultimi dei nostri rifornimenti di guerra sono in viaggio verso ⟦Silithus=Silitus⟧ e dovrebbero arrivare entro un giorno. Va' e porta onore all'⟦Horde=Orda⟧!", "." },
  ["5ead1ead49db9a13"] = { "Prima di iniziare una caccia, è saggio chiedere a qualcuno cosa stai cercando prima di cominciare a cercarlo.", "." },
  ["5eb5359fe848b092"] = { "Sono <un/una> <cacciatore/cacciatrice> e voglio addestrarmi.", "." },
  ["5eb7b7d947b11c98"] = { "Il maresciallo Windsor ti stava aspettando, {name}. Purtroppo al momento è indisposto. Dovrebbe tornare a breve.", "." },
  ["5eb82da2c17a426a"] = { "La pace non è che un sogno fugace! Che regni l'INCUBO!", "." },
  ["5eb8ec37b541d721"] = { "Al'tabim, ho perso i miei ⟦Zandalar Demoniac's Mantle=Coprispalle Demoniaci degli Zandalari⟧. Puoi aiutarmi?", "." },
  ["5ebcb0dc24342c63"] = { "Di che compito si tratta?", "." },
  ["5ec0e84ea28a4879"] = { "Torna da me quando avrai più addestramento. Randal Worth, laggiù, può aiutarti in questo.", "." },
  ["5ec31bc944a07299"] = { "Cosa serve per il calderone al ⟦Felstone Field=Campo di Vilpietra⟧?", "." },
  ["5ec872c6290c9796"] = { "Scappare su colline! Aspetta! Noi già su colline!", "." },
  ["5ec9dfa903eb795b"] = { "Sì, comandante!", "." },
  ["5ecc75125ec512da"] = { "Grazie agli sforzi di tutti ora abbiamo tutti i lingotti di ferro che ci servono. Chiedi a uno degli altri se c'è qualcos'altro che dovresti raccogliere là fuori per lo sforzo bellico. Io vedrò se riesco a staccare un po' prima per farmi una partita a carte.", "." },
  ["5edb9f0f0db26339"] = { "{name} conquista la miniera! Se nessuno la contende, l'⟦Horde=Orda⟧ la controllerà fra 1 minuto!", "." },
  ["5edcdc31cc0ded94"] = { "Hai l'aria di chi si è perso.", "." },
  ["5edf8adb95527836"] = { "Prendilo! Torna da me se il potere dell'Occhio dovesse affievolirsi.", "." },
  ["5ee06338aeafd91a"] = { "Al villaggio c'è un saggio che si chiama ⟦Narm Skychaser=Narm Preda Cielo⟧. Può proseguire il tuo apprendimento sulla via dello Sciamano.", "." },
  ["5ee489aeedae3517"] = { "La pagherete cara quando tornerò dagli abissi!", "." },
  ["5efb11afdf764656"] = { "Il culto di Al'Aketh sostiene che Al'Akir, il «Signore del Vento», ci salverà dalle nostre attuali sventure qui su Zephras. Se Al'Akir è reale ed è davvero il sovrano di ⟦Skywall=Celaria⟧, perché gli spiriti del vento si sono rifiutati di parlare di lui per così tanto tempo?\r\n\nO non è reale o, peggio ancora, è reale e non è benevolo come sostiene il culto. In ogni caso, niente di ciò che il culto sta facendo è un bene per noi gente comune.", "." },
  ["5efd42b68f4725be"] = { "Ehi, Raven...", "." },
  ["5efde0453f398670"] = { "Cerchi Mishiki. Ha una capanna a sud, nel ⟦Sen'jin Village=Villaggio di Sen'jin⟧.", "." },
})
